import{_ as a,H as e,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"03 | 快速上手（一）：LobeChat+AI网关+Ollama打造高可用大模型集群","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是 Ollama ？","slug":"什么是-ollama","link":"#什么是-ollama","children":[]},{"level":2,"title":"Ollama 部署 DeepSeek-R1 实战","slug":"ollama-部署-deepseek-r1-实战","link":"#ollama-部署-deepseek-r1-实战","children":[{"level":3,"title":"环境准备","slug":"环境准备","link":"#环境准备","children":[]},{"level":3,"title":"安装 Ollama","slug":"安装-ollama","link":"#安装-ollama","children":[]},{"level":3,"title":"部署与测试 DeepSeek-R1","slug":"部署与测试-deepseek-r1","link":"#部署与测试-deepseek-r1","children":[]},{"level":3,"title":"1. 在容器内下载模型和拉起 *","slug":"_1-在容器内下载模型和拉起","link":"#_1-在容器内下载模型和拉起","children":[]},{"level":3,"title":"2. 将模型文件挂载进容器（推荐）","slug":"_2-将模型文件挂载进容器-推荐","link":"#_2-将模型文件挂载进容器-推荐","children":[]},{"level":3,"title":"模型为什么不思考？","slug":"模型为什么不思考","link":"#模型为什么不思考","children":[]}]},{"level":2,"title":"API 访问","slug":"api-访问","link":"#api-访问","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"DeepSeek应用开发实战/03｜快速上手（一）：LobeChat+AI网关+Ollama打造高可用大模型集群.md","filePath":"DeepSeek应用开发实战/03｜快速上手（一）：LobeChat+AI网关+Ollama打造高可用大模型集群.md","lastUpdated":1795486824000}'),t={name:"DeepSeek应用开发实战/03｜快速上手（一）：LobeChat+AI网关+Ollama打造高可用大模型集群.md"};function p(l,s,h,k,o,r){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="_03-快速上手-一-lobechat-ai网关-ollama打造高可用大模型集群" tabindex="-1">03 | 快速上手（一）：LobeChat+AI网关+Ollama打造高可用大模型集群 <a class="header-anchor" href="#_03-快速上手-一-lobechat-ai网关-ollama打造高可用大模型集群" aria-label="Permalink to &quot;03 | 快速上手（一）：LobeChat+AI网关+Ollama打造高可用大模型集群&quot;">​</a></h1><p>你好，我是邢云阳。</p><p>学完我专门为你准备的前置课程，相信对于目前主流的 AI 开发到底是在开发什么，你已经有了一定的认知，这对于你学习后面的课程会有很大的帮助。</p><p>从这一章起，我会为你揭秘在云公司里，针对不同的用户场景，DeepSeek 模型是如何部署的。相信你在学完这一章的内容后，只要手里有服务器资源，都能够轻松复刻出同款效果来，并且还可以举一反三，搞定其他开源模型的私有化部署。</p><p>接下来的两节课，我会先介绍一种相对简单且在业界进行私有化模型的 AI 应用开发时极为常用的方案，即通过 LobeChat + 网关 + Ollama 打造高可用的部署方案。今天，我们先用Ollama 将 DeepSeek 模型拉起来，下一节课，我们再来实现高可用集群。</p><h2 id="什么是-ollama" tabindex="-1">什么是 Ollama ？ <a class="header-anchor" href="#什么是-ollama" aria-label="Permalink to &quot;什么是 Ollama ？&quot;">​</a></h2><p>首先来了解一下 Ollama。Ollama 是一个专为在本地机器上便捷部署和运行大型语言模型（LLM）而设计的开源框架，它可以用简单的命令行快捷部署多种大模型，例如 DeepSeek、Qwen、Llama3 等等模型。</p><p>除此之外呢，Ollama 自身还会通过权重量化技术，调整模型权重，并通过分块加载与缓存机制以及 GPU/CPU 灵活调度等技术，使得模型能够降低对硬件的要求，提高资源利用率。以DeepSeek-R1 的蒸馏模型 DeepSeek-R1-Distill-Qwen-7B 为例，最小也需要 14 G 的显存。但 Ollama 通过对模型的量化，可以显著降低对于显存的占用。</p><p>讲到这，可能会有同学还是不理解什么是量化，我举一个简单的例子做一下类比。我们在使用微信时，经常会互相发一些图片。如果我们在收到图片时不点下载原图，图片画质就不清晰（分辨率低），但图片大小可能只有几百 K，占用存储空间小；如果我们点了下载原图，图片更加清晰（分辨率高），但占用存储空间大。原版模型和量化模型之间的关系呢，大概就类似于原图和非原图之间的关系，如果为了节省显存，就需要对模型进行量化。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/1.png" alt=""></a></p><p>Ollama 有一个非常出色的特性，这也是众多开发者选择它的关键原因，即 Ollama 为所有支持的模型封装了统一的 API，并且兼容 OpenAI 数据格式。这一点至关重要，由于模型是由不同公司或团队训练的，每种模型原本都提供各自的开发接口。因此，Ollama 进行统一封装后，用户在使用时就变得极为便捷。</p><p>比如，我们编写 Agent 代码时，就会把标准的 OpenAI SDK 的 base_url 参数和模型名称做出修改。同样地，如果通过 Ollama 访问 DeepSeek，只需将 base_url 修改为 Ollama 的地址即可。后期如果需要切换到 Qwen 模型，也无需再修改 base_url，只需更换模型名称即可。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client = OpenAI(</span></span>
<span class="line"><span>   api_key=os.getenv(&quot;AliDeep&quot;),</span></span>
<span class="line"><span>   base_url=&quot;https://dashscope.aliyuncs.com/compatible-mode/v1&quot;</span></span>
<span class="line"><span>)</span></span></code></pre></div><h2 id="ollama-部署-deepseek-r1-实战" tabindex="-1">Ollama 部署 DeepSeek-R1 实战 <a class="header-anchor" href="#ollama-部署-deepseek-r1-实战" aria-label="Permalink to &quot;Ollama 部署 DeepSeek-R1 实战&quot;">​</a></h2><p>OK，讲了这么多，接下来，我们就进入到这节课的实战环节。</p><h3 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to &quot;环境准备&quot;">​</a></h3><p>为了节省资源，我是在联通云上开通了一台带有 2 张 T4 卡的云服务器，操作系统是 Ubuntu22.04。T4 卡的单卡显存是 16 G，理论上至多能跑满血版的 7B 模型，但由于使用的是Ollama 部署，因此我们可以以 32B 模型为例做演示。只要你学会了 32B 模型的部署，之后不管是部署 1.5B 还是 671B，方法都一模一样，没有任何区别。</p><p>首先使用 nvidia-smi 命令，确认 GPU 卡的驱动已经装好，可以被识别。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root@aitest:~# nvidia-smi</span></span>
<span class="line"><span>Sun Feb 16 13:56:24 2025</span></span>
<span class="line"><span>+-----------------------------------------------------------------------------+</span></span>
<span class="line"><span>| NVIDIA-SMI 515.76       Driver Version: 515.76       CUDA Version: 11.7     |</span></span>
<span class="line"><span>|-------------------------------+----------------------+----------------------+</span></span>
<span class="line"><span>| GPU  Name        Persistence-M| Bus-Id        Disp.A | Volatile Uncorr. ECC |</span></span>
<span class="line"><span>| Fan  Temp  Perf  Pwr:Usage/Cap|         Memory-Usage | GPU-Util  Compute M. |</span></span>
<span class="line"><span>|                               |                      |               MIG M. |</span></span>
<span class="line"><span>|===============================+======================+======================|</span></span>
<span class="line"><span>|   0  Tesla T4            Off  | 00000000:00:07.0 Off |                    0 |</span></span>
<span class="line"><span>| N/A   42C    P0    25W /  70W |      2MiB / 15360MiB |      0%      Default |</span></span>
<span class="line"><span>|                               |                      |                  N/A |</span></span>
<span class="line"><span>+-------------------------------+----------------------+----------------------+</span></span>
<span class="line"><span>|   1  Tesla T4            Off  | 00000000:00:08.0 Off |                    0 |</span></span>
<span class="line"><span>| N/A   43C    P0    26W /  70W |      2MiB / 15360MiB |      5%      Default |</span></span>
<span class="line"><span>|                               |                      |                  N/A |</span></span>
<span class="line"><span>+-------------------------------+----------------------+----------------------+</span></span>
<span class="line"><span>+-----------------------------------------------------------------------------+</span></span>
<span class="line"><span>| Processes:                                                                  |</span></span>
<span class="line"><span>|  GPU   GI   CI        PID   Type   Process name                  GPU Memory |</span></span>
<span class="line"><span>|        ID   ID                                                   Usage      |</span></span>
<span class="line"><span>|=============================================================================|</span></span>
<span class="line"><span>|  No running processes found                                                 |</span></span>
<span class="line"><span>+-----------------------------------------------------------------------------+</span></span></code></pre></div><p>可以看到两张 T4 卡已经就绪了。</p><h3 id="安装-ollama" tabindex="-1">安装 Ollama <a class="header-anchor" href="#安装-ollama" aria-label="Permalink to &quot;安装 Ollama&quot;">​</a></h3><p>我们用官方推荐的 Docker 方式部署 Ollama，便于进行版本的管理与测试。</p><p>首先将 Ollama 镜像下载到本地，由于国内无法访问 DockerHub，因此大家可以使用后面命令中的代理地址访问：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker.1ms.run/ollama/ollama:0.5.11</span></span></code></pre></div><p>之后使用命令启动 Ollama 容器：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8880:11434</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gpus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DeepSeek-R1-1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker.1ms.run/oll</span></span></code></pre></div><p>这条命令的意思是，首先将容器的 11434 端口映射到宿主机的 8880 端口，11434 即 Ollama提供 API 访问的端口。–gpus device=0 表示该容器要使用 GPU 0 号卡，怎么知道 GPU 卡的编号的呢？是在前面执行 nvidia-smi 命令时知道的。</p><p>根据前面 nvidia-smi 命令的执行结果，两张 Tesla T4 的编号分别是 0 和 1。–nameDeepSeek-R1-1 是给容器起一个名字，叫 abc 都可以，只要你喜欢。最后是下载下来的容器镜像的名称。</p><p>如果一切正常，启动后，就会返回容器的 ID。接着我们通过 docker ps 命令，就可以查询到容器的信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root@aitest:~# docker run -dp 8880:11434 --gpus device=0 --name DeepSeek-R1-1 doc</span></span>
<span class="line"><span>7049f65fd9d34392c26355174f4701c1b2c5aa718cdc168d19a982f0519d7635</span></span>
<span class="line"><span>root@aitest:~# docker ps</span></span>
<span class="line"><span>CONTAINER ID   IMAGE                                 COMMAND               CREATE</span></span>
<span class="line"><span>7049f65fd9d3   docker.1ms.run/ollama/ollama:0.5.11   &quot;/bin/ollama serve&quot;   10 sec</span></span></code></pre></div><p>这一步，经常会报如下的错误：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@aitest:~# docker run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dp </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8880</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11434</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> --gpus device=0 --name DeepSeek-R1-1 doc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bd74646a26c6a539aa7660eb664caa585dba188720f0975701b73d87263b6cdf</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker: Error response </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> daemon: could </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">not</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> device driver </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capabi</span></span></code></pre></div><p>这是因为服务器的 NVIDIA Container Toolkit 没有装，需要执行如下命令安装一下：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">distribution=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(. </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">etc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">release;echo $ID$VERSION_ID)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">curl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">L https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">nvidia</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">io/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nvidia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gpgkey | sudo apt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">curl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">L https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">nvidia</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">io/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nvidia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">distribution/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nvidia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">docker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lis</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">apt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-get</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> update</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">apt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> install </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y nvidia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">systemctl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> docker</span></span></code></pre></div><p>安装完成后，执行 docker info 命令，确保 docker 守护进程已经正确配置 GPU 支持。命令和输出如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root@aitest:~# docker info | grep -i nvidia</span></span>
<span class="line"><span>Runtimes: io.containerd.runc.v2 nvidia runc</span></span></code></pre></div><p>此时再重新 docker run，就可以将 Ollama 容器拉起了。</p><h3 id="部署与测试-deepseek-r1" tabindex="-1">部署与测试 DeepSeek-R1 <a class="header-anchor" href="#部署与测试-deepseek-r1" aria-label="Permalink to &quot;部署与测试 DeepSeek-R1&quot;">​</a></h3><p>Ollama 官方提供了一个可视化的模型仓库，便于我们了解 Ollama 已经支持了哪些模型，以及下载模型。仓库的地址是：<a href="https://ollama.com/library" target="_blank" rel="noreferrer">https://ollama.com/library</a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/2.png" alt=""></a></p><p>点开链接后，第一个就是 DeepSeek-R1 模型，分为 1.5b 到 671b 多个版本。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/3.png" alt=""></a></p><p>点进去之后可以选择模型版本以及看到模型运行命令，更新记录等。</p><p>这里我介绍两种 Ollama 拉起 DeepSeek-R1 的方案。</p><h3 id="_1-在容器内下载模型和拉起" tabindex="-1">1. 在容器内下载模型和拉起 * <a class="header-anchor" href="#_1-在容器内下载模型和拉起" aria-label="Permalink to &quot;1. 在容器内下载模型和拉起 *&quot;">​</a></h3><p>我们需要进入到 Ollama 容器的内部，去执行模型运行命令。进入容器的命令为：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">你的容器名称或</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /bin/bash</span></span></code></pre></div><p>然后执行模型运行命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ollama run deepseek-r1:32b</span></span></code></pre></div><p>输出如下，由于本地没有模型，所以，会先在模型仓库下载模型，我们需要耐心等待模型下载完毕。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/4.png" alt=""></a></p><p>下载完成后，就会加载模型，直到出现 success，模型就加载好了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/5.png" alt=""></a></p><p>直接输入对话，测试效果。例如：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/6.png" alt=""></a></p><p>可以看到，模型带有 DeepSeek-R1 标志性的 &lt;​think&gt;&lt;​/think&gt; 也就是深度思考，但是由于我们问的问题太简单了，模型认为不需要深度思考就能回答，因此就直接回答了。</p><h3 id="_2-将模型文件挂载进容器-推荐" tabindex="-1">2. 将模型文件挂载进容器（推荐） <a class="header-anchor" href="#_2-将模型文件挂载进容器-推荐" aria-label="Permalink to &quot;2. 将模型文件挂载进容器（推荐）&quot;">​</a></h3><p>我更推荐接下来的这种方法，因为下一节我们讲负载均衡方案时，需要起两个 Ollama 容器，因此用这种方式只下载一次模型文件就可以，比较方便。</p><p>执行如下命令，在服务器上安装 Ollama 工具。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ollama.com/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>之后直接将模型下载到本地：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ollama pull deepseek-r1:32b</span></span></code></pre></div><p>启动容器，将模型挂载进去，需要注意 Ollama 在 ubuntu 服务器上的默认是模型文件存放目录 /usr/share/ollama/.ollama/models，但是在容器中的目录是 /root/.ollama/models，挂载时要写成服务器目录: 容器目录的格式，注意不要写反了。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8880:11434</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runtime=nvidia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gpus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DeepSeek-R1-1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:/root/.ollama/models</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker.1ms.run/ollama/ollama:0.5.11</span></span></code></pre></div><p>最后查看容器中的模型是否已经运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root@aitest:~# docker ps</span></span>
<span class="line"><span>CONTAINER ID   IMAGE                                 COMMAND               CREATE</span></span>
<span class="line"><span>9a44f04e78f7   docker.1ms.run/ollama/ollama:0.5.11   &quot;/bin/ollama serve&quot;   6 minu</span></span>
<span class="line"><span>root@aitest:~# docker exec -it 9a44f04e78f7 ollama list</span></span>
<span class="line"><span>NAME               ID              SIZE     MODIFIED</span></span>
<span class="line"><span>deepseek-r1:32b    38056bbcbb2d    19 GB    About an hour ago</span></span></code></pre></div><h3 id="模型为什么不思考" tabindex="-1">模型为什么不思考？ <a class="header-anchor" href="#模型为什么不思考" aria-label="Permalink to &quot;模型为什么不思考？&quot;">​</a></h3><p>在上文中，我们问 “hello”，DeepSeek 并没有思考。但是我们用官方版本的去问同样的问题，会发现，官方版的无论简单问题还是复杂问题都会思考：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/7.png" alt=""></a></p><p>这是什么原因呢？我们使用如下命令看一下 deepseek-r1:32b 的聊天模板。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ollama show --modelfile deepseek-r1:32b</span></span></code></pre></div><p>输出如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/8.png" alt=""></a></p><p>可以看到在 &lt;｜ Assistant｜ &gt; 后面直接就是跟的 Content，没有可以强调 &lt;​think&gt; 的事情，因此就相当于把是否 think 的主动权交给大模型了。这个其实是对的，如果每一个问题无论简单与否都要思考，会劳民伤财，费时费钱。但这个事情反过来看，如果大模型的能力不能达到极致，在遇到我们想让它思考的问题时，它不思考，体验性又不好。所以这也是官方版本做了强制 think 的原因吧。</p><p>那我们如何像官方一样强制 think 呢？其实很简单，按官方教程描述，只需要加一个 think 标签即可。</p><p>操作步骤是这样的。首先将聊天模板保存下来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ollama show --modelfile deepseek-r1:32b &gt; Modelfile</span></span></code></pre></div><p>之后，在 &lt;｜ Assistant｜ &gt; 之后加上 &lt;​think&gt;\\n，如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/9.png" alt=""></a></p><p>之后基于 Modelfile 创建一个新的模型：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ollama create deepseek-r1-think:32b -f ./Modelfile</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/10.png" alt=""></a></p><p>这时，再按照前面讲的将模型文件挂载进容器的启动方式，启动容器。</p><p>进入容器后，执行一下 ollama list，可以看到现在有两个模型了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/11.png" alt=""></a></p><p>使用如下命令，将模型 deepseek-r1-think:32b 运行起来，然后测试：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ollama run deepseek-r1-think:32b</span></span></code></pre></div><p>测试结果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/12.png" alt=""></a></p><p>再问相同的问题，模型具备了思考能力。</p><h2 id="api-访问" tabindex="-1">API 访问 <a class="header-anchor" href="#api-访问" aria-label="Permalink to &quot;API 访问&quot;">​</a></h2><p>最后，我们看一下，Ollama 的 API 访问。由于 Ollama 的 API 兼容了 OpenAI 的数据结构，因此测试非常简单，直接 curl 一下即可：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8880/v1/chat/completions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-H </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-d </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   &quot;model&quot;: &quot;deepseek-r1-think:32b&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;messages&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   {&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;hello&quot;}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&#39;</span></span></code></pre></div><p>结果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/DeepSeek%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/03/13.png" alt=""></a></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课，我们开启了 DeepSeek-R1 模型的私有化部署之路。事实上，在 DeepSeek 模型爆火之前，很多同学都是在使用 OpenAI，通义千问等商业模型，对于私有化模型基本没有部署经验。因此我先选择了一种相对非常容易上手的方式，来带你入门。下面我们做个总结。</p><p>Ollama 致力于让用户可以以极简的方式快速部署运行开源模型。为了减少对于显存的占用，Ollama 对模型进行了量化处理，因此我们才可以在一张 16GB 显存的 T4 卡上，体验DeepSeek-R1:32B 模型。</p><p>除此之外，Ollama 还对各个大模型进行了统一的 API 封装，API 兼容 OpenAI 数据格式，因此用户可以直接通过访问 OpenAI 模型的方式去访问 Ollama 拉起的模型，非常方便。</p><p>最后，我们还结合 DeepSeek-R1 的一个典型特征，深度思考，进行了测试，并解决了模型遇到简单问题不思考的问题。如果你手头上有服务器，或者个人笔记本的显卡是 3090、4090 等相对不错的显卡，可以尝试按文章内容实践一遍，加深理解。</p><p>除此之外，我再扩展一点内容，在部署与测试 DeepSeek-R1 小节，我讲了用 Docker 拉起大模型的两种方式，这两种方式无一例外都需要下载模型文件。因此在实际生产中，我们不会这么做。我们会提前将模型文件下载到本地后，基于 Ollama 镜像再打一个新镜像，新镜像便包含了模型文件。这样后期使用时，直接将镜像拉起便可以使用。还有一种方法，是将模型文件放置在对象存储，使用时进行挂载，后续课程里我还会讲解这种方法。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>我在测试 API 访问时，提示词非常短，因此返回的速度很快。如果是一个复杂一点的提示词，例如：请帮我写一段 Python 的加减法程序，就会等好长时间才能看到回复。你可以思考一下，如何能调整一下，让用户不等这么久呢？</p><p>欢迎你在留言区展示你的思考过程，我们一起探讨。如果你觉得这节课的内容对你有帮助的话，也欢迎你分享给其他朋友，我们下节课再见！</p>`,104)])])}const g=a(t,[["render",p]]);export{c as __pageData,g as default};
